function showPanel(panel){
  document.querySelectorAll('.eg-panel').forEach(item=>item.classList.toggle('active',item===panel));
  document.querySelectorAll('.eg-tab').forEach(tab=>{const active=tab.dataset.tab==='lost';tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));if(active)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current')});
  document.querySelectorAll('.elma-main-tab').forEach(tab=>{const active=tab.dataset.elmaTab==='lost';tab.classList.toggle('active',active);if(active)tab.setAttribute('aria-current','page');else tab.removeAttribute('aria-current')});
  $('.hero')?.style.setProperty('display','none');$('.mapwrap')?.style.setProperty('display','none');$('#elmaHomeWidgets')?.classList.remove('home-active');
}
function goServices(){const mainTab=document.querySelector('.elma-main-tab[data-elma-tab="services"]');if(mainTab){mainTab.click();return}if(window.elmaSelectMainTab)window.elmaSelectMainTab('services');else{const panel=$('.eg-panel[data-panel="services"]');if(panel){document.querySelectorAll('.eg-panel').forEach(item=>item.classList.toggle('active',item===panel));document.querySelector('.eg-tab[data-tab="services"]')?.classList.add('active')}}}
function toast(text,error=false){const node=$('#egLostToast');if(!node)return;node.textContent=text;node.classList.toggle('error',error);node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),3200)}
function setStatus(text,error=false){const node=$('#egLostStatus');if(node){node.textContent=text;node.classList.toggle('error',error)}}
function maskedOwnerName(account){const raw=String(account?.displayName||account?.email?.split('@')[0]?.replace(/[._-]+/g,' ')||'').trim(),parts=raw.split(/\s+/).filter(Boolean);if(!parts.length)return'Elma Go kullanıcısı';if(parts.length===1)return parts[0]+' *';const surname=parts.at(-1),stars='*'.repeat(Math.max(2,Math.min(8,surname.length-1)));return parts[0]+' '+surname.charAt(0).toLocaleUpperCase('tr-TR')+stars}
function position(){if(window.elmaUserPosition)return Promise.resolve(window.elmaUserPosition);return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('Konum desteklenmiyor.'));navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:15000,maximumAge:300000})})}
async function resolveViewerCity(){if(viewerCity)return viewerCity;if(cityResolution)return cityResolution;cityResolution=(async()=>{setStatus('İlanlar hazırlanıyor…');try{const current=await position(),lat=current.coords.latitude,lon=current.coords.longitude;viewerCoords={lat,lon};const response=await withTimeout(fetch('https://photon.komoot.io/reverse?lat='+encodeURIComponent(lat)+'&lon='+encodeURIComponent(lon)+'&lang=tr&limit=1'),12000,'Konum şehre çevrilemedi.');if(!response.ok)throw new Error('Konum şehre çevrilemedi.');const properties=(await response.json()).features?.[0]?.properties||{},candidates=[properties.state,properties.city,properties.county,properties.district].filter(Boolean).map(cityKey);viewerCity=cities.find(city=>candidates.some(value=>value===cityKey(city)||value.includes(cityKey(city))))||'';viewerDistrict=[properties.county,properties.district,properties.city].find(value=>(districts[viewerCity]||[]).some(name=>cityKey(name)===cityKey(value)))||'';if(!viewerCity)throw new Error('Bulunduğun şehir belirlenemedi.');try{localStorage.setItem('elmaViewerCity',viewerCity)}catch{}setStatus(viewerCity+' ilanları gösteriliyor.');return viewerCity}catch(error){try{viewerCity=localStorage.getItem('elmaViewerCity')||'Amasya'}catch{viewerCity='Amasya'}viewerCoords=null;viewerDistrict='';setStatus(viewerCity+' ilanları gösteriliyor. Konum izni gerekmiyor.');return viewerCity}})();return cityResolution}

async function connectFirebase(){
  if(api){if(!viewerCity){cityResolution=null;await resolveViewerCity();if(viewerCity)subscribeListings()}return api}
  const [appModule,authModule,dbModule,storageModule]=await Promise.all([import(FIREBASE.app),import(FIREBASE.auth),import(FIREBASE.db),import(FIREBASE.storage)]);
  for(let i=0;i<30&&!appModule.getApps().length;i++)await new Promise(resolve=>setTimeout(resolve,50));
  const app=appModule.getApps()[0]||appModule.initializeApp(APP_CONFIG);
  const auth=authModule.getAuth(app),db=dbModule.getFirestore(app),storage=storageModule.getStorage(app);
  api={...authModule,...dbModule,...storageModule,auth,db,storage};
  authModule.onAuthStateChanged(auth,next=>{user=next;subscribeRequests();subscribeOutgoingRequests();subscribeMyListings();render();prefillUser()});
  await resolveViewerCity();if(viewerCity)subscribeListings();return api;
}
function subscribeListings(){
  if(!api||!viewerCity||unsubscribeListings)return;
  const source=api.query(api.collection(api.db,'lostFoundListings'),api.where('city','==',viewerCity),api.limit(100));
  unsubscribeListings=api.onSnapshot(source,snapshot=>{if(listingSnapshotReady)snapshot.docChanges().filter(change=>change.type==='added').forEach(change=>notifyNearbyListing({id:change.doc.id,...change.doc.data()}));listings=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));listingSnapshotReady=true;setStatus(viewerCity+' ilanları gösteriliyor.');render();checkMatches()},error=>setStatus(error.code==='permission-denied'?'İlanları görüntülemek için veritabanı izni gerekli.':'İlanlar şu anda alınamadı.',true));
}
function subscribeMyListings(){unsubscribeMine?.();unsubscribeMine=null;myListings=[];if(!api||!user){updateAccountSummary();return}const source=api.query(api.collection(api.db,'lostFoundListings'),api.where('ownerUid','==',user.uid),api.limit(100));unsubscribeMine=api.onSnapshot(source,snapshot=>{myListings=snapshot.docs.map(doc=>({id:doc.id,...doc.data()}));updateAccountSummary();render();checkMatches()},()=>updateAccountSummary())}
function subscribeRequests(){
  unsubscribeRequests?.();unsubscribeRequests=null;requests=[];
  if(!api||!user){render();return}
  const source=api.query(api.collection(api.db,'lostFoundContacts'),api.where('ownerUid','==',user.uid));
  unsubscribeRequests=api.onSnapshot(source,snapshot=>{requests=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));render();updateAccountSummary()},()=>{});
}
function subscribeOutgoingRequests(){unsubscribeOutgoing?.();unsubscribeOutgoing=null;outgoingRequests=[];if(!api||!user){render();return}const source=api.query(api.collection(api.db,'lostFoundContacts'),api.where('requesterUid','==',user.uid));unsubscribeOutgoing=api.onSnapshot(source,snapshot=>{outgoingRequests=snapshot.docs.map(doc=>({id:doc.id,...doc.data()})).sort((a,b)=>(dateValue(b.createdAt)||0)-(dateValue(a.createdAt)||0));render()},()=>{})}
function filteredItems(){
  const source=mode==='mine'?myListings:listings;return source.filter(item=>{
    if(mode!=='mine'&&(!viewerCity||cityKey(itemCity(item))!==cityKey(viewerCity)))return false;
    if(blockedOwners.has(item.ownerUid))return false;
    if(mode==='lost'&&item.kind!=='lost'||mode==='found'&&item.kind!=='found'||mode==='mine'&&item.ownerUid!==user?.uid)return false;
    if(mode!=='mine'&&!activeListing(item)||category!=='all'&&item.category!==category)return false;
    if(mode!=='mine'&&nearOnly&&distanceKm(viewerCoords,item.coords)>5)return false;
    const haystack=normalize([item.title,item.description,item.location,item.district,item.address,item.category,item.ownerName].join(' '));
    return !query||haystack.includes(query);
  });
}
function updateMetrics(items){
  const all=(mode==='mine'?myListings:listings).filter(activeListing),values={egLostMetricAll:all.length,egLostMetricLost:all.filter(item=>item.kind==='lost').length,egLostMetricFound:all.filter(item=>item.kind==='found').length,egLostVisibleCount:items.length+' ilan'};
  Object.entries(values).forEach(([id,value])=>{const node=document.getElementById(id);if(node)node.textContent=value});
}
function render(){
  const list=$('#egLostResults');if(!list)return;list.replaceChildren();
  const tools=$('#egLostTools'),metrics=$('#egLostDashboard'),smart=$('.eg-lost-smartbar');if(tools)tools.hidden=mode==='requests';if(smart)smart.hidden=mode==='requests';if(metrics)metrics.hidden=mode==='requests';
  if(mode==='requests'){renderRequests(list);updateFeedTitle();return}
  if(mode==='mine'&&!user){empty(list,'İlanlarını görmek için hesabınla giriş yap.');updateMetrics([]);updateFeedTitle();return}
  const items=filteredItems();updateMetrics(items);updateFeedTitle();
  if(!items.length){empty(list,query?'Aramana uygun ilan bulunamadı.':mode==='mine'?'Henüz bir ilan oluşturmadın.':'Bu bölümde aktif ilan yok.');return}
  items.forEach(item=>list.appendChild(listingCard(item)));
}
function updateFeedTitle(){const title=$('#egLostFeedTitle');if(title)title.textContent=mode==='lost'?'Kayıp ilanları':mode==='found'?'Bulunan eşyalar':mode==='mine'?'İlanlarım':mode==='requests'?'İletişim talepleri':'Son ilanlar'}
