  const title=document.createElement('h3');title.textContent=item.title||'İsimsiz eşya';const desc=document.createElement('p');desc.className='eg-lost-desc';desc.textContent=item.description||'';const matched=bestMatch(item),badge=document.createElement('span');if(item.urgent){badge.className='eg-lost-urgent';badge.textContent='ACİL KAYIP'}else if(matched){badge.className='eg-lost-match';badge.textContent='%'+matched.score+' olası eşleşme'}else if(!activeListing(item)){badge.className='eg-lost-match eg-lost-expired';badge.textContent=item.status==='solved'?'Çözüldü':'Süresi doldu'}
