function openDetail(item){currentDetail=item;const layer=$('#egLostDetailLayer'),content=$('#egLostDetailContent');if(!layer||!content)return;content.replaceChildren();const hero=document.createElement('div');hero.className='eg-lost-detail-hero';const type=document.createElement('small');type.textContent=(item.kind==='found'?'BULUNAN EŞYA':'KAYIP EŞYA')+' • '+(item.category||'DİĞER');const title=document.createElement('h2');title.textContent=item.title||'İsimsiz eşya';hero.append(type,title);content.append(hero,detailRow('Konum',visibleLocation(item)),detailRow('Tarih',trDate(item.happenedAt)),detailRow('İlan sahibi',item.ownerName),detailRow('Güven puanı','%'+trustScore(item.ownerUid)),detailRow('Açıklama',item.description));if(item.verificationQuestion)content.append(detailRow('Sahiplik sorusu',item.verificationQuestion));const matched=bestMatch(item);if(matched)content.append(detailRow('Olası eşleşme','%'+matched.score+' • '+matched.item.title));const actions=document.createElement('div');actions.className='eg-lost-detail-actions';if(item.ownerUid===user?.uid){if(activeListing(item))actions.append(action('Düzenle','',()=>{closeDetail();openForm(item)}),action('Çözüldü','primary',()=>solve(item)));else if(item.status!=='solved')actions.append(action('Yeniden yayımla','primary',()=>renew(item)))}else if(activeListing(item))actions.append(action('İletişim talebi','primary',()=>{closeDetail();openContact(item)}),action('Şikâyet','',()=>report(item)),action('Engelle','danger',()=>blockOwner(item)));content.append(actions);layer.classList.add('show')}
